/**
 * Renders the committed data-source document from the reference records, so the
 * document cannot drift away from the data. `docs/DATA.md` is generated by this
 * function and `src/data/dataDoc.test.ts` fails if the file and the records
 * disagree.
 */
import type { HistoricalReference } from '../core/provenance';

const TITLE = '# Data sources and confidence';

const INTRO = [
  'Generated from `src/data/references.ts` by `renderDataDoc()`. Do not edit by hand:',
  'change the records and regenerate.',
  '',
  'Two kinds of record live here:',
  '',
  '- **Sourced estimates** name an organisation-level public source and the date it was published.',
  '  Where sources disagree, the range is recorded rather than a single figure.',
  '- **Game abstractions** are scenario decisions with no published figure behind them. They are',
  '  labelled as such and must state how the real-world quantity was turned into a game number.',
  '',
  'Nothing in this project asserts a precise real-world inventory, and no published CEP is treated',
  'as a guaranteed hit probability. Hex ranges are theatre distances on a compressed map, not a',
  '1:1 conversion from kilometres.',
].join('\n');

const CATEGORY_ORDER: HistoricalReference['category'][] = [
  'weapon',
  'arsenal',
  'launcher',
  'facility',
  'nuclear-material',
  'scenario',
  'politics',
];

const CATEGORY_TITLE: Record<HistoricalReference['category'], string> = {
  weapon: 'Weapon systems',
  arsenal: 'Missile and drone inventories',
  launcher: 'Launchers',
  facility: 'Facilities',
  'nuclear-material': 'Nuclear material',
  scenario: 'Scenario starting values',
  politics: 'Political and economic context',
};

/** Human-readable unit slug; the raw strings are storage keys, not display text. */
export function prettyUnit(unit?: string): string {
  if (!unit) return '';
  if (unit === 'km_range') return 'km';
  if (unit === 'game_hex_range') return 'hex';
  return unit;
}

/** A cell that cannot break the table. */
function cell(text: string): string {
  return text.replace(/\|/g, '\\|').replace(/\s+/g, ' ').trim();
}

function valueText(ref: HistoricalReference): string {
  const unit = ref.unit ? ` ${prettyUnit(ref.unit)}` : '';
  if (ref.min !== undefined && ref.max !== undefined) {
    return ref.min === ref.max ? `${ref.min}${unit}` : `${ref.min}–${ref.max}${unit}`;
  }
  return ref.value !== undefined ? `${ref.value}${unit}` : '—';
}

function sourceText(ref: HistoricalReference): string {
  if (!ref.sourceName) return 'game abstraction';
  const date = ref.sourcePublishedAt ? ` (${ref.sourcePublishedAt})` : '';
  return `${ref.sourceName}${date}`;
}

export function renderDataDoc(references: readonly HistoricalReference[]): string {
  const lines: string[] = [TITLE, '', INTRO, ''];

  for (const category of CATEGORY_ORDER) {
    const rows = references.filter((ref) => ref.category === category);
    if (rows.length === 0) continue;
    lines.push(`## ${CATEGORY_TITLE[category]}`, '');
    lines.push('| Item | Value | Source | Confidence | Game mapping |');
    lines.push('| --- | --- | --- | --- | --- |');
    for (const ref of [...rows].sort((a, b) => a.id.localeCompare(b.id))) {
      lines.push(
        `| ${cell(ref.subjectId)} | ${cell(valueText(ref))} | ${cell(sourceText(ref))} | ${cell(
          `${ref.evidenceType} / ${ref.confidence}`,
        )} | ${cell(ref.gameMapping)} |`,
      );
    }
    lines.push('');
  }

  lines.push(
    '---',
    '',
    'Every record is last reviewed on the date in `lastReviewed` and is validated by',
    '`src/data/provenance.test.ts`, which fails if a required value loses its provenance.',
    '',
  );
  return lines.join('\n');
}
